def convert_bst(root):
    running, node = 0, root
    while node is not None:
        if node.right is None:
            running += node.val
            node.val = running
            node = node.left
            continue
        succ = node.right
        while succ.left is not None and succ.left is not node:
            succ = succ.left
        if succ.left is None:
            succ.left = node                 # thread back, go right first
            node = node.right
        else:
            succ.left = None
            running += node.val
            node.val = running
            node = node.left
    return root
